1	use std::env;
2	use std::io::Read;
3	use std::process::ExitCode;
4	
5	/// Authentication core shared by `sign` and `verify`.
6	///
7	/// This module owns everything about *computing* format-1 tags: key
8	/// validation and decoding, the key-version business rule (its legal range
9	/// and the canonical integer both entry points authenticate with), the
10	/// canonical byte encoding of the authenticated content, the HMAC-SHA256
11	/// computation itself, and constant-time tag comparison. It knows nothing
12	/// about command lines, JSON records, standard output or exit codes — the
13	/// subcommands own all of that presentation (including each one's input
14	/// grammar and error wording) and map these results to output lines and exit
15	/// statuses.
16	mod auth {
17	    use hmac::{
18	        Hmac, Mac,
19	        digest::KeyInit,
20	    };
21	    use sha2::Sha256;
22	
23	    /// Record format version written by `sign` and required by `verify`.
24	    pub const FORMAT_VERSION: u32 = 1;
25	    /// Algorithm name written by `sign` and required by `verify`.
26	    pub const ALGORITHM: &str = "HMAC-SHA256";
27	    /// Smallest legal key version; the low endpoint is itself a usable version.
28	    pub const MIN_KEY_VERSION: u32 = 1;
29	    /// Largest legal key version. The version travels in the record and in the
30	    /// format-1 encoding as a `u32`, so the bound is exactly `u32::MAX`.
31	    pub const MAX_KEY_VERSION: u32 = u32::MAX;
32	    /// Domain separator that also records the format version, so tags computed
33	    /// by different versions of the encoding can never collide.
34	    const DOMAIN_SEPARATOR: &[u8] = b"authnote-sign-v1";
35	
36	    /// One computed authentication tag: a full HMAC-SHA256 output.
37	    pub type Tag = [u8; 32];
38	
39	    /// Shared key validation for `sign` and `verify`: non-empty even-length
40	    /// hex. The rejected value is never included in the message.
41	    pub fn validate_key_hex(key: &str) -> Result<(), String> {
42	        if key.is_empty() || key.len() % 2 != 0 || !key.bytes().all(|b| b.is_ascii_hexdigit()) {
43	            return Err("--key must be a non-empty, even-length hexadecimal string".to_string());
44	        }
45	        Ok(())
46	    }
47	
48	    /// Decode key text that has passed `validate_key_hex` into raw bytes.
49	    /// The bytes feed the MAC only; they never appear in any record.
50	    pub fn decode_key(hex: &str) -> Vec<u8> {
51	        decode_hex(hex).expect("key was validated as hex")
52	    }
53	
54	    /// Apply the key-version business rule to an exact integer value and
55	    /// return its canonical `u32` form.
56	    ///
57	    /// Both entry points funnel through this one function, so the legal range
58	    /// (`MIN_KEY_VERSION..=MAX_KEY_VERSION`) and the integer that actually
59	    /// enters the record and the format-1 encoding live in exactly one place:
60	    /// `sign` hands over the value parsed from its decimal command-line text,
61	    /// `verify` the value read from a strict JSON integer. What differs is
62	    /// only each side's input grammar (leading zeros and signs are accepted
63	    /// by neither JSON nor the CLI in the same way) — that parsing stays with
64	    /// the caller; the rule itself does not.
65	    pub fn canonical_key_version(value: i128) -> Option<u32> {
66	        (i128::from(MIN_KEY_VERSION)..=i128::from(MAX_KEY_VERSION))
67	            .contains(&value)
68	            .then(|| value as u32)
69	    }
70	
71	    /// Fixed range-rejection wording for a record's `key_version`. The message
72	    /// names the member and the bounds, never the rejected value.
73	    pub fn key_version_range_error() -> String {
74	        format!(
75	            "member \"key_version\" is outside the supported range {}..={}",
76	            MIN_KEY_VERSION, MAX_KEY_VERSION
77	        )
78	    }
79	
80	    /// Fixed range-rejection wording for sign's `--key-version` option. The
81	    /// message names the option and the bounds, never the rejected text.
82	    pub fn key_version_option_error() -> String {
83	        format!(
84	            "--key-version must be a decimal integer between {} and {}",
85	            MIN_KEY_VERSION, MAX_KEY_VERSION
86	        )
87	    }
88	
89	    /// Compute the format-1 authentication tag over the given content.
90	    ///
91	    /// Both `sign` (to emit a tag) and `verify` (to recompute the expected
92	    /// tag) go through this single path, so the two can never drift apart.
93	    pub fn compute_tag(key: &[u8], key_id: &str, key_version: u32, fields: &[String]) -> Tag {
94	        let message = encode_message(key_id, key_version, fields);
95	        let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(key)
96	            .expect("HMAC accepts keys of any length");
97	        mac.update(&message);
98	        mac.finalize().into_bytes().into()
99	    }
100	
101	    /// Compare a recomputed tag with the tag from a record, in constant time
102	    /// so a mismatch cannot be recovered one byte at a time through timing.
103	    pub fn tags_match(expected: &Tag, given: &[u8]) -> bool {
104	        if expected.len() != given.len() {
105	            return false;
106	        }
107	        let mut diff = 0u8;
108	        for (a, b) in expected.iter().zip(given.iter()) {
109	            diff |= a ^ b;
110	        }
111	        diff == 0
112	    }
113	
114	    /// Canonical byte encoding of the authenticated content.
115	    ///
116	    /// Layout (all integers big-endian, all text UTF-8, no trimming or escaping):
117	    ///   DOMAIN_SEPARATOR ("authnote-sign-v1", 16 ASCII bytes)
118	    ///   u64 length of key-id, then key-id bytes
119	    ///   u32 key version
120	    ///   u64 field count
121	    ///   for each field in order: u64 length of field, then field bytes
122	    ///
123	    /// Length prefixes make field boundaries unambiguous: ["ab","c"] and
124	    /// ["a","bc"] encode differently, as do zero fields and one empty field.
125	    fn encode_message(key_id: &str, key_version: u32, fields: &[String]) -> Vec<u8> {
126	        let mut out = Vec::new();
127	        out.extend_from_slice(DOMAIN_SEPARATOR);
128	        push_len_prefixed(&mut out, key_id.as_bytes());
129	        out.extend_from_slice(&key_version.to_be_bytes());
130	        out.extend_from_slice(&(fields.len() as u64).to_be_bytes());
131	        for field in fields {
132	            push_len_prefixed(&mut out, field.as_bytes());
133	        }
134	        out
135	    }
136	
137	    fn push_len_prefixed(out: &mut Vec<u8>, bytes: &[u8]) {
138	        out.extend_from_slice(&(bytes.len() as u64).to_be_bytes());
139	        out.extend_from_slice(bytes);
140	    }
141	
142	    pub fn decode_hex(s: &str) -> Result<Vec<u8>, String> {
143	        (0..s.len())
144	            .step_by(2)
145	            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| e.to_string()))
146	            .collect()
147	    }
148	
149	    pub fn hex_encode(bytes: &[u8]) -> String {
150	        bytes.iter().map(|b| format!("{b:02x}")).collect()
151	    }
152	}
153	
154	fn main() -> ExitCode {
155	    let args: Vec<String> = match decode_args() {
156	        Ok(args) => args,
157	        Err(msg) => {
158	            eprintln!("authnote: {msg}");
159	            return ExitCode::from(2);
160	        }
161	    };
162	    match args.first().map(String::as_str) {
163	        Some("--version") if args.len() == 1 => {
164	            println!("authnote 0.1.0");
165	            ExitCode::SUCCESS
166	        }
167	        Some("sign") => sign(&args[1..]),
168	        Some("verify") => verify(&args[1..]),
169	        _ => {
170	            eprintln!("Usage: authnote --version");
171	            eprintln!(
172	                "       authnote sign --key HEX --key-id ID --key-version N [--field TEXT]..."
173	            );
174	            eprintln!("       authnote verify --key HEX");
175	            ExitCode::from(2)
176	        }
177	    }
178	}
179	
180	/// Decode the process arguments (excluding the program name) as UTF-8 text.
181	///
182	/// `env::args()` panics on arguments that are not valid UTF-8; decoding via
183	/// `args_os()` lets us report the problem as an ordinary usage error instead.
184	/// The raw bytes are never printed: the message only states *that* an
185	/// argument could not be decoded, not what it contained.
186	fn decode_args() -> Result<Vec<String>, String> {
187	    let mut out = Vec::new();
188	    for (index, arg) in env::args_os().skip(1).enumerate() {
189	        match arg.into_string() {
190	            Ok(s) => out.push(s),
191	            Err(_) => {
192	                return Err(format!(
193	                    "argument {} is not valid UTF-8 text; all arguments must be decodable text",
194	                    index + 1
195	                ));
196	            }
197	        }
198	    }
199	    Ok(out)
200	}
201	
202	/// Shared command-line option grammar for `sign` and `verify`.
203	///
204	/// Both subcommands accept the same two spellings for every option:
205	///   --name value     (the following argument is the value, even when it
206	///                    itself starts with "--")
207	///   --name=value     (everything after the first '=' is the value; further
208	///                    '=' characters stay part of the value)
209	/// and the two forms may be mixed freely.
210	///
211	/// What differs between the subcommands is only *which* option names are
212	/// allowed and whether a name may repeat, so each caller supplies its own
213	/// option table. Values that fail are never quoted back in error messages:
214	/// the messages name known options only, never the rejected text (which may
215	/// be a mistyped secret).
216	mod options {
217	    /// How many times an option name may appear on one command line.
218	    #[derive(Clone, Copy, PartialEq, Eq)]
219	    pub(super) enum Multiplicity {
220	        /// At most once; a second occurrence is a usage error.
221	        Single,
222	        /// Any number of times; values are kept in order of appearance.
223	        Repeated,
224	    }
225	
226	    /// One option accepted by a subcommand.
227	    pub(super) struct Spec {
228	        pub(super) name: &'static str,
229	        pub(super) multiplicity: Multiplicity,
230	    }
231	
232	    /// A matched option occurrence: the option's index in the table and its
233	    /// value for this occurrence.
234	    pub(super) struct Occurrence {
235	        pub(super) spec_index: usize,
236	        pub(super) value: String,
237	    }
238	
239	    /// Parse `args` against `specs`, preserving order of appearance.
240	    ///
241	    /// Error precedence (first problem wins, left to right):
242	    /// missing value for an option, repeated single-use option, unknown
243	    /// option or bare argument. Callers run their own semantic validation
244	    /// (hex, ranges, ...) afterwards, so grammar problems are always
245	    /// reported before invalid values.
246	    pub(super) fn parse(args: &[String], specs: &[Spec]) -> Result<Vec<Occurrence>, String> {
247	        let mut out = Vec::new();
248	        let mut seen_once = vec![false; specs.len()];
249	
250	        let mut i = 0;
251	        while i < args.len() {
252	            let arg = &args[i];
253	            // Support both "--opt value" and "--opt=value" forms. With '='
254	            // the value is everything after the FIRST '='; '=' characters
255	            // inside the value are left untouched.
256	            let (name, inline_value) = match arg.split_once('=') {
257	                Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
258	                _ => (arg.as_str(), None),
259	            };
260	            let spec_index = match specs.iter().position(|s| s.name == name) {
261	                Some(idx) => idx,
262	                // Never echo the unrecognized argument itself: it may be a
263	                // misplaced secret (e.g. a key value whose option name was
264	                // mistyped or whose value was consumed by another option).
265	                None => return Err(unknown_option_error(specs)),
266	            };
267	            let value = match inline_value {
268	                Some(v) => v,
269	                None => {
270	                    // The immediately following argument is the value, with
271	                    // no "--"-prefix special-casing: a field or key id may
272	                    // legitimately start with two dashes.
273	                    i += 1;
274	                    match args.get(i) {
275	                        Some(v) => v.clone(),
276	                        None => return Err(format!("option {name} requires a value")),
277	                    }
278	                }
279	            };
280	            if specs[spec_index].multiplicity == Multiplicity::Single && seen_once[spec_index] {
281	                return Err(format!("option {name} must be given exactly once"));
282	            }
283	            seen_once[spec_index] = true;
284	            out.push(Occurrence { spec_index, value });
285	            i += 1;
286	        }
287	        Ok(out)
288	    }
289	
290	    /// Build the fixed "unrecognized" message for a subcommand, listing only
291	    /// that subcommand's known option names. The rejected argument is never
292	    /// included.
293	    fn unknown_option_error(specs: &[Spec]) -> String {
294	        let names = specs
295	            .iter()
296	            .map(|s| s.name)
297	            .collect::<Vec<_>>()
298	            .join(", ");
299	        if specs.len() == 1 {
300	            format!("unrecognized option or argument (the only known option is {names})")
301	        } else {
302	            format!("unrecognized option or argument (known options: {names})")
303	        }
304	    }
305	}
306	
307	fn sign(args: &[String]) -> ExitCode {
308	    match parse_sign_args(args).and_then(validate_sign_args) {
309	        Ok(opts) => {
310	            let key_bytes = auth::decode_key(&opts.key);
311	            // `opts.key_version` is already the canonical integer produced by
312	            // the shared key-version rule, so there is no second conversion
313	            // here: the same value goes into the record and the tag.
314	            let tag = auth::compute_tag(&key_bytes, &opts.key_id, opts.key_version, &opts.fields);
315	            println!("{}", render_record(&opts.key_id, opts.key_version, &opts.fields, &tag));
316	            ExitCode::SUCCESS
317	        }
318	        Err(msg) => {
319	            eprintln!("authnote sign: {msg}");
320	            ExitCode::from(2)
321	        }
322	    }
323	}
324	
325	/// Render one format-1 record as the single JSON line `sign` prints.
326	///
327	/// Pure presentation: member order, escaping, lowercase tag hex and the
328	/// trailing newline (added by the caller's `println!`) are fixed here. The
329	/// key is not a parameter — it never enters the record.
330	fn render_record(key_id: &str, key_version: u32, fields: &[String], tag: &auth::Tag) -> String {
331	    let fields_json = fields
332	        .iter()
333	        .map(|f| format!("\"{}\"", json_escape(f)))
334	        .collect::<Vec<_>>()
335	        .join(",");
336	    format!(
337	        "{{\"format\":{},\"algorithm\":\"{}\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
338	        auth::FORMAT_VERSION,
339	        auth::ALGORITHM,
340	        json_escape(key_id),
341	        key_version,
342	        fields_json,
343	        auth::hex_encode(tag),
344	    )
345	}
346	
347	/// Validated sign inputs. `key_version` is already the canonical integer
348	/// produced by the shared key-version rule, so `sign` converts nothing again.
349	struct SignOptions {
350	    key: String,
351	    key_id: String,
352	    key_version: u32,
353	    fields: Vec<String>,
354	}
355	
356	/// sign's option table: the three credential/metadata options are single
357	/// use; only --field may repeat. Names double as their stable indices.
358	const SIGN_OPTIONS: &[options::Spec] = &[
359	    options::Spec {
360	        name: "--key",
361	        multiplicity: options::Multiplicity::Single,
362	    },
363	    options::Spec {
364	        name: "--key-id",
365	        multiplicity: options::Multiplicity::Single,
366	    },
367	    options::Spec {
368	        name: "--key-version",
369	        multiplicity: options::Multiplicity::Single,
370	    },
371	    options::Spec {
372	        name: "--field",
373	        multiplicity: options::Multiplicity::Repeated,
374	    },
375	];
376	const SIGN_KEY_INDEX: usize = 0;
377	const SIGN_KEY_ID_INDEX: usize = 1;
378	const SIGN_KEY_VERSION_INDEX: usize = 2;
379	
380	/// Raw sign options straight off the command line: values are unvalidated
381	/// text, so the option grammar (in `options::parse`) stays separate from the
382	/// value rules applied in `validate_sign_args`.
383	struct RawSignOptions {
384	    key: String,
385	    key_id: String,
386	    key_version: String,
387	    fields: Vec<String>,
388	}
389	
390	fn parse_sign_args(args: &[String]) -> Result<RawSignOptions, String> {
391	    let mut key: Option<String> = None;
392	    let mut key_id: Option<String> = None;
393	    let mut key_version: Option<String> = None;
394	    let mut fields: Vec<String> = Vec::new();
395	
396	    for occurrence in options::parse(args, SIGN_OPTIONS)? {
397	        match occurrence.spec_index {
398	            SIGN_KEY_INDEX => key = Some(occurrence.value),
399	            SIGN_KEY_ID_INDEX => key_id = Some(occurrence.value),
400	            SIGN_KEY_VERSION_INDEX => key_version = Some(occurrence.value),
401	            // Field values are appended in order of appearance; repeats,
402	            // empty strings and text starting with "--" are kept verbatim.
403	            _ => fields.push(occurrence.value),
404	        }
405	    }
406	
407	    let key = key.ok_or("missing required option --key")?;
408	    let key_id = key_id.ok_or("missing required option --key-id")?;
409	    let key_version = key_version.ok_or("missing required option --key-version")?;
410	    Ok(RawSignOptions {
411	        key,
412	        key_id,
413	        key_version,
414	        fields,
415	    })
416	}
417	
418	/// sign's own key-version input grammar: non-empty ASCII decimal text, then
419	/// the shared range rule. Leading zeros are command-line text, not JSON, so
420	/// "007" is the integer 7; signs, fractions, exponents and embedded
421	/// whitespace are not part of the grammar. The rejected text is never quoted.
422	fn parse_key_version_text(text: &str) -> Result<u32, String> {
423	    let value = (!text.is_empty() && text.bytes().all(|b| b.is_ascii_digit()))
424	        .then(|| text.parse::<i128>().ok())
425	        .flatten();
426	    match value.and_then(auth::canonical_key_version) {
427	        Some(version) => Ok(version),
428	        None => Err(auth::key_version_option_error()),
429	    }
430	}
431	
432	fn validate_sign_args(opts: RawSignOptions) -> Result<SignOptions, String> {
433	    // Never echo the key back in error messages.
434	    auth::validate_key_hex(&opts.key)?;
435	    if opts.key_id.is_empty() {
436	        return Err("--key-id must not be empty".to_string());
437	    }
438	    let key_version = parse_key_version_text(&opts.key_version)?;
439	    Ok(SignOptions {
440	        key: opts.key,
441	        key_id: opts.key_id,
442	        key_version,
443	        fields: opts.fields,
444	    })
445	}
446	
447	// ---------------------------------------------------------------------------
448	// verify
449	// ---------------------------------------------------------------------------
450	
451	fn verify(args: &[String]) -> ExitCode {
452	    // verify deliberately shares sign's option grammar through the common
453	    // parser but declares its own, narrower table: --key is the only known
454	    // option, so every sign-only option (--key-id, --key-version, --field)
455	    // is rejected here as unrecognized. Values that fail are never echoed
456	    // (they could be a mistyped secret).
457	    const VERIFY_OPTIONS: &[options::Spec] = &[options::Spec {
458	        name: "--key",
459	        multiplicity: options::Multiplicity::Single,
460	    }];
461	
462	    let parse = (|| -> Result<String, String> {
463	        let occurrences = options::parse(args, VERIFY_OPTIONS)?;
464	        // The parser enforces "at most one --key"; take it if present.
465	        let key = occurrences
466	            .first()
467	            .map(|o| o.value.clone())
468	            .ok_or("missing required option --key")?;
469	        auth::validate_key_hex(&key)?;
470	        Ok(key)
471	    })();
472	
473	    let key_hex = match parse {
474	        Ok(key) => key,
475	        Err(msg) => {
476	            eprintln!("authnote verify: {msg}");
477	            return ExitCode::from(2);
478	        }
479	    };
480	
481	    // Read the whole standard input. It must be one JSON record and nothing
482	    // else; trailing non-whitespace is a malformed invocation, not a mismatch.
483	    let mut input = Vec::new();
484	    if let Err(e) = std::io::stdin().read_to_end(&mut input) {
485	        eprintln!("authnote verify: failed to read standard input: {e}");
486	        return ExitCode::from(2);
487	    }
488	
489	    let outcome = verify_input(&input, &key_hex);
490	    match outcome {
491	        VerifyOutcome::Valid => {
492	            println!("{{\"valid\":true}}");
493	            ExitCode::SUCCESS
494	        }
495	        VerifyOutcome::Mismatch => {
496	            println!("{{\"valid\":false}}");
497	            ExitCode::from(1)
498	        }
499	        VerifyOutcome::Invalid(msg) => {
500	            eprintln!("authnote verify: {msg}");
501	            ExitCode::from(2)
502	        }
503	    }
504	}
505	
506	#[derive(Debug)]
507	enum VerifyOutcome {
508	    Valid,
509	    Mismatch,
510	    Invalid(String),
511	}
512	
513	fn verify_input(input: &[u8], key_hex: &str) -> VerifyOutcome {
514	    let text = match std::str::from_utf8(input) {
515	        Ok(t) => t,
516	        // Still parse to distinguish a structurally invalid record from a
517	        // record whose text merely contains bytes Rust rejects; JSON itself
518	        // forbids raw non-UTF-8, so this is always "corrupt input" here.
519	        Err(_) => return VerifyOutcome::Invalid("input is not valid UTF-8 JSON text".to_string()),
520	    };
521	
522	    let value = match json::parse_single(text) {
523	        Ok(v) => v,
524	        Err(msg) => return VerifyOutcome::Invalid(msg),
525	    };
526	    let record = match record_from_json(&value) {
527	        Ok(r) => r,
528	        Err(msg) => return VerifyOutcome::Invalid(msg),
529	    };
530	
531	    let key_bytes = auth::decode_key(key_hex);
532	    let expected_tag = auth::compute_tag(
533	        &key_bytes,
534	        &record.key_id,
535	        record.key_version,
536	        &record.fields,
537	    );
538	
539	    if auth::tags_match(&expected_tag, &record.tag) {
540	        VerifyOutcome::Valid
541	    } else {
542	        VerifyOutcome::Mismatch
543	    }
544	}
545	
546	/// Decode the tag as exactly 32 bytes of case-insensitive hexadecimal.
547	fn decode_tag(s: &str) -> Result<Vec<u8>, String> {
548	    if s.len() != 64 || !s.bytes().all(|b| b.is_ascii_hexdigit()) {
549	        return Err("tag must be exactly 64 hexadecimal characters (32 bytes)".to_string());
550	    }
551	    auth::decode_hex(s).map_err(|e| format!("tag is not valid hexadecimal: {e}"))
552	}
553	
554	struct AuthRecord {
555	    key_id: String,
556	    key_version: u32,
557	    fields: Vec<String>,
558	    tag: Vec<u8>,
559	}
560	
561	/// Validate the decoded JSON value as exactly one format-1 authentication
562	/// record and pull out the authenticated fields. Structural problems (missing
563	/// members, wrong types, duplicates inside `fields`, ...) are caller errors:
564	/// they must produce exit 2, never a `{"valid":false}` mismatch result.
565	fn record_from_json(value: &json::JsonValue) -> Result<AuthRecord, String> {
566	    let obj = match value {
567	        json::JsonValue::Object(entries) => entries,
568	        _ => return Err("record must be a single JSON object".to_string()),
569	    };
570	
571	    // Require precisely the six documented members, each present exactly once;
572	    // the parser already rejects duplicate member names, and an empty object
573	    // naturally fails the "missing required member" checks below.
574	    let mut format: Option<&json::JsonValue> = None;
575	    let mut algorithm: Option<&json::JsonValue> = None;
576	    let mut key_id: Option<&json::JsonValue> = None;
577	    let mut key_version: Option<&json::JsonValue> = None;
578	    let mut fields: Option<&json::JsonValue> = None;
579	    let mut tag: Option<&json::JsonValue> = None;
580	    for (name, val) in obj {
581	        let slot = match name.as_str() {
582	            "format" => &mut format,
583	            "algorithm" => &mut algorithm,
584	            "key_id" => &mut key_id,
585	            "key_version" => &mut key_version,
586	            "fields" => &mut fields,
587	            "tag" => &mut tag,
588	            // Do not echo the unknown member name: it comes from the input
589	            // record, which error messages must never quote back.
590	            _ => return Err("record contains an unexpected member".to_string()),
591	        };
592	        if slot.is_some() {
593	            // The strict parser rejects duplicates already; keep a defense in
594	            // depth without quoting the member name from the input twice.
595	            return Err("record contains a duplicate member".to_string());
596	        }
597	        *slot = Some(val);
598	    }
599	
600	    // Unsupported format versions must be reported as such explicitly: we do
601	    // not silently fall back to the current rules and compute a result. The
602	    // decision is purely "is the integer spelling 1 or not", so zero, negative
603	    // and integers wider than the machine's usual integer capacity all say
604	    // "unsupported version" rather than "corrupt input"; non-integer spellings
605	    // (strings, fractions, exponents, leading zeros) stay type/grammar errors.
606	    let format = format.ok_or("record is missing required member \"format\"")?;
607	    match format {
608	        json::JsonValue::Number(n) if n.is_one() => {}
609	        json::JsonValue::Number(_) => {
610	            return Err("unsupported record format version; only format 1 is supported".to_string())
611	        }
612	        _ => return Err("member \"format\" must be an integer".to_string()),
613	    }
614	
615	    let algorithm = algorithm.ok_or("record is missing required member \"algorithm\"")?;
616	    match algorithm {
617	        json::JsonValue::String(s) if s == auth::ALGORITHM => {}
618	        json::JsonValue::String(_) => {
619	            return Err(
620	                "unsupported algorithm in record; only HMAC-SHA256 is supported".to_string(),
621	            )
622	        }
623	        _ => return Err("member \"algorithm\" must be a string".to_string()),
624	    }
625	
626	    let key_id = key_id.ok_or("record is missing required member \"key_id\"")?;
627	    let key_id = match key_id {
628	        json::JsonValue::String(s) if !s.is_empty() => s.clone(),
629	        json::JsonValue::String(_) => {
630	            return Err("member \"key_id\" must not be empty".to_string())
631	        }
632	        _ => return Err("member \"key_id\" must be a string".to_string()),
633	    };
634	
635	    let key_version = key_version.ok_or("record is missing required member \"key_version\"")?;
636	    let key_version = match key_version {
637	        json::JsonValue::Number(n) => {
638	            // Type/writing problems are caught by the strict parser and the
639	            // non-Number arm below; here the only question the shared
640	            // key-version rule answers is whether the exact integer is in
641	            // range. An integer wider than `i128` yields `None` from
642	            // `as_i128` and is rejected by the same rule as a small
643	            // out-of-range value — it must never be truncated or wrapped, and
644	            // never misreported as an unsupported record format.
645	            match n.as_i128().and_then(auth::canonical_key_version) {
646	                Some(version) => version,
647	                None => return Err(auth::key_version_range_error()),
648	            }
649	        }
650	        _ => return Err("member \"key_version\" must be an integer".to_string()),
651	    };
652	
653	    let fields_val = fields.ok_or("record is missing required member \"fields\"")?;
654	    let fields = match fields_val {
655	        json::JsonValue::Array(items) => {
656	            let mut out = Vec::with_capacity(items.len());
657	            for item in items {
658	                match item {
659	                    json::JsonValue::String(s) => out.push(s.clone()),
660	                    _ => {
661	                        return Err(
662	                            "every element of member \"fields\" must be a string".to_string()
663	                        )
664	                    }
665	                }
666	            }
667	            out
668	        }
669	        _ => return Err("member \"fields\" must be an array of strings".to_string()),
670	    };
671	
672	    let tag_val = tag.ok_or("record is missing required member \"tag\"")?;
673	    let tag = match tag_val {
674	        json::JsonValue::String(s) => decode_tag(s)?,
675	        _ => return Err("member \"tag\" must be a string".to_string()),
676	    };
677	
678	    Ok(AuthRecord {
679	        key_id,
680	        key_version,
681	        fields,
682	        tag,
683	    })
684	}
685	
686	fn json_escape(s: &str) -> String {
687	    let mut out = String::with_capacity(s.len());
688	    for c in s.chars() {
689	        match c {
690	            '"' => out.push_str("\\\""),
691	            '\\' => out.push_str("\\\\"),
692	            '\n' => out.push_str("\\n"),
693	            '\r' => out.push_str("\\r"),
694	            '\t' => out.push_str("\\t"),
695	            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
696	            c => out.push(c),
697	        }
698	    }
699	    out
700	}
