1333	        // Illegal spellings/ranges are corrupt input regardless of the key;
1334	        // none is accepted as integer 7 or wrapped/truncated into range.
1335	        let zeros = "a".repeat(64);
1336	        let raw_record = |token: &str| {
1337	            format!(
1338	                "{{\"format\":1,\"algorithm\":\"HMAC-SHA256\",\"key_id\":\"id\",\
1339	                 \"key_version\":{token},\"fields\":[\"x\"],\"tag\":\"{zeros}\"}}"
1340	            )
