1577	        assert!(parse_single("1e3").is_err());
1578	        assert!(parse_single("01").is_err());
1579	        assert!(parse_single("-01").is_err());
1580	        // string escapes incl. surrogate pairs and lone surrogates
1581	        assert_eq!(
1582	            parse_single("\"😀\"").unwrap(),
1583	            json::JsonValue::String("😀".to_string())
1584	        );
1585	        assert_eq!(
1586	            parse_single("\"\\ud83d\\ude00\"").unwrap(),
1587	            json::JsonValue::String("😀".to_string())
1588	        );
1589	        assert!(parse_single("\"\\ud83d\"").is_err());
1590	        assert!(parse_single("\"\\udc00\"").is_err());
1591	        assert!(parse_single("\"\\x\"").is_err());
1592	        assert!(parse_single("\"\n\"").is_err()); // raw control character
