384	fn verify_key_version_range_endpoints_are_normal_versions() {
385	    // Both endpoints of 1..=4294967295 are ordinary usable versions: with the
386	    // correct key the record verifies (exit 0, exactly one {"valid":true}
387	    // line, empty stderr). The key version is independent of the record's
388	    // format version: a key version other than 1 must never be reported as an
389	    // unsupported format.
390	    for (token, golden) in [("1", KV_TAG_V1), ("4294967295", KV_TAG_VMAX)] {
391	        let rec = kv_record(token, golden);
