572	fn verify_huge_and_nonpositive_format_versions_are_unsupported_not_corrupt() {
573	    // A legal JSON decimal integer for `format` — including zero, negatives and
574	    // integers beyond the platform's usual integer capacity — must read as "an
575	    // unsupported record format version", never as corrupt JSON and never
576	    // truncated to 1. The record otherwise satisfies every format-1 rule.
577	    let key = "00ff";
578	    let wrong_key = "0102";
579	    let tag = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
580	    let record = |format_token: &str| {
581	        format!(
582	            r#"{{"format":{format_token},"algorithm":"HMAC-SHA256","key_id":"id","key_version":1,"fields":[],"tag":"{tag}"}}"#
583	        )
584	    };
585	    let unsupported: &[&str] = &[
586	        "0",
587	        "-0",
588	        "-1",
589	        "2",
590	        "170141183460469231731687303715884105728", // 2^127, one past i128::MAX
591	        "999999999999999999999999999999999999999999999999999",
592	        "-170141183460469231731687303715884105729", // -(2^127 + 1)
593	        "-999999999999999999999999999999999999999999999999999",
594	    ];
595	    for token in unsupported {
596	        for used_key in [key, wrong_key] {
597	            let out = run_verify(used_key, record(token).as_bytes());
598	            assert_eq!(
599	                out.status.code(),
600	                Some(2),
601	                "token {token}: expected exit 2, key={used_key}"
602	            );
603	            assert!(out.stdout.is_empty(), "token {token}: stdout must be empty");
604	            let stderr = String::from_utf8(out.stderr).expect("stderr must be UTF-8");
605	            let lower = stderr.to_lowercase();
606	            assert!(
607	                lower.contains("unsupported"),
608	                "token {token}: must say the version is unsupported, key={used_key}: {stderr}"
609	            );
610	            assert!(
611	                lower.contains("format"),
612	                "token {token}: message must name the record format version: {stderr}"
613	            );
614	            assert!(
615	                stderr.contains("format 1"),
616	                "token {token}: message must say only format 1 is supported: {stderr}"
617	            );
618	            // Never echo the rejected digits, the key or record content.
619	            assert!(
620	                !stderr.contains(token),
621	                "token {token}: stderr echoed the rejected number: {stderr}"
622	            );
623	            assert!(!stderr.contains(used_key), "stderr echoed the key: {stderr}");
624	            assert!(
625	                !lower.contains("out of supported range"),
626	                "token {token}: must not blame JSON integer capacity: {stderr}"
627	            );
628	        }
629	    }
630	}
