772	// ---------------------------------------------------------------------------
773	// Minimal JSON parser (objects, arrays, strings, integers, true/false/null).
774	// ---------------------------------------------------------------------------
775	
776	#[derive(Debug, Clone)]
777	enum Json {
778	    Null,
779	    // Retained for parser completeness; records carry no boolean values.
780	    #[allow(dead_code)]
781	    Bool(bool),
782	    Num(i64),
783	    Str(String),
784	    Arr(Vec<Json>),
785	    Obj(Vec<(String, Json)>),
786	}
787	
788	impl Json {
789	    fn parse(s: &str) -> Json {
790	        let mut p = Parser {
791	            chars: s.chars().collect(),
792	            pos: 0,
793	        };
794	        p.ws();
795	        let v = p.value();
796	        p.ws();
797	        assert_eq!(p.pos, p.chars.len(), "trailing data after JSON record: {s}");
798	        v
799	    }
800	
801	    fn as_str(&self) -> &str {
802	        match self {
803	            Json::Str(s) => s,
804	            other => panic!("expected JSON string, got {other:?}"),
805	        }
806	    }
807	
808	    fn as_i64(&self) -> i64 {
809	        match self {
810	            Json::Num(n) => *n,
811	            other => panic!("expected JSON number, got {other:?}"),
812	        }
813	    }
814	
815	    fn as_array(&self) -> &[Json] {
816	        match self {
817	            Json::Arr(a) => a,
818	            other => panic!("expected JSON array, got {other:?}"),
819	        }
820	    }
821	
822	    fn as_object(&self) -> &[(String, Json)] {
823	        match self {
824	            Json::Obj(o) => o,
825	            other => panic!("expected JSON object, got {other:?}"),
826	        }
827	    }
828	
829	    fn get(&self, key: &str) -> &Json {
830	        let obj = self.as_object();
831	        let idx = obj
832	            .iter()
833	            .position(|(k, _)| k == key)
834	            .unwrap_or_else(|| panic!("missing key {key:?} in {self:?}"));
835	        &obj[idx].1
836	    }
837	
838	    /// Every string value anywhere in the document.
839	    fn strings(&self, out: &mut Vec<String>) {
840	        match self {
841	            Json::Str(s) => out.push(s.clone()),
842	            Json::Arr(a) => a.iter().for_each(|v| v.strings(out)),
843	            Json::Obj(o) => o.iter().for_each(|(_, v)| v.strings(out)),
844	            Json::Null | Json::Bool(_) | Json::Num(_) => {}
845	        }
846	    }
847	}
848	
849	struct Parser {
850	    chars: Vec<char>,
851	    pos: usize,
852	}
853	
854	impl Parser {
855	    fn ws(&mut self) {
856	        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
857	            self.pos += 1;
858	        }
859	    }
860	
861	    fn bump(&mut self) -> char {
862	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
863	        let c = self.chars[self.pos];
864	        self.pos += 1;
865	        c
866	    }
867	
868	    fn expect(&mut self, want: char) {
869	        assert!(self.pos < self.chars.len(), "expected {want:?}, found end of JSON");
870	        let got = self.chars[self.pos];
871	        assert_eq!(got, want, "expected {want:?} at position {}", self.pos);
872	        self.pos += 1;
873	    }
874	
875	    fn value(&mut self) -> Json {
876	        self.ws();
877	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
878	        match self.chars[self.pos] {
879	            '{' => self.object(),
880	            '[' => self.array(),
881	            '"' => Json::Str(self.string()),
882	            't' | 'f' => self.boolean(),
883	            'n' => self.null(),
884	            c if c == '-' || c.is_ascii_digit() => self.number(),
885	            c => panic!("unexpected character {c:?} in JSON"),
886	        }
887	    }
888	
889	    fn object(&mut self) -> Json {
890	        self.expect('{');
891	        let mut entries = Vec::new();
892	        self.ws();
893	        if self.chars[self.pos] == '}' {
894	            self.pos += 1;
895	            return Json::Obj(entries);
896	        }
897	        loop {
898	            self.ws();
899	            let key = self.string();
900	            self.ws();
901	            self.expect(':');
902	            let val = self.value();
903	            entries.push((key, val));
904	            self.ws();
905	            match self.bump() {
906	                ',' => continue,
907	                '}' => break,
908	                c => panic!("bad object separator {c:?}"),
909	            }
910	        }
911	        Json::Obj(entries)
912	    }
913	
914	    fn array(&mut self) -> Json {
915	        self.expect('[');
916	        let mut items = Vec::new();
917	        self.ws();
918	        if self.chars[self.pos] == ']' {
919	            self.pos += 1;
920	            return Json::Arr(items);
921	        }
922	        loop {
923	            items.push(self.value());
924	            self.ws();
925	            match self.bump() {
926	                ',' => continue,
927	                ']' => break,
928	                c => panic!("bad array separator {c:?}"),
929	            }
930	        }
931	        Json::Arr(items)
932	    }
933	
934	    fn string(&mut self) -> String {
935	        self.expect('"');
936	        let mut out = String::new();
937	        loop {
938	            match self.bump() {
939	                '"' => break,
940	                '\\' => match self.bump() {
941	                    '"' => out.push('"'),
942	                    '\\' => out.push('\\'),
943	                    '/' => out.push('/'),
944	                    'b' => out.push('\u{0008}'),
945	                    'f' => out.push('\u{000c}'),
946	                    'n' => out.push('\n'),
947	                    'r' => out.push('\r'),
948	                    't' => out.push('\t'),
949	                    'u' => {
950	                        let hi = self.hex4();
951	                        let c = if (0xD800..=0xDBFF).contains(&hi) {
952	                            assert_eq!(self.bump(), '\\');
953	                            assert_eq!(self.bump(), 'u');
954	                            let lo = self.hex4();
955	                            assert!(
956	                                (0xDC00..=0xDFFF).contains(&lo),
957	                                "bad low surrogate {lo:x}"
958	                            );
959	                            char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
960	                                .expect("bad surrogate pair")
961	                        } else {
962	                            char::from_u32(hi).expect("bad unicode escape")
963	                        };
964	                        out.push(c);
965	                    }
966	                    c => panic!("bad escape \\{c}"),
967	                },
968	                // Raw control bytes must not appear unescaped in JSON text.
969	                c if (c as u32) < 0x20 => panic!("unescaped control character {c:?} in JSON"),
970	                c => out.push(c),
971	            }
972	        }
973	        out
974	    }
975	
976	    fn hex4(&mut self) -> u32 {
977	        let mut v = 0u32;
978	        for _ in 0..4 {
979	            let c = self.bump();
980	            v = v * 16 + c.to_digit(16).unwrap_or_else(|| panic!("bad hex digit {c:?}"));
981	        }
982	        v
983	    }
984	
985	    fn number(&mut self) -> Json {
986	        let start = self.pos;
987	        if self.chars[self.pos] == '-' {
988	            self.pos += 1;
989	        }
990	        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
991	            self.pos += 1;
992	        }
993	        let text: String = self.chars[start..self.pos].iter().collect();
994	        Json::Num(text.parse().unwrap_or_else(|_| panic!("bad number {text}")))
995	    }
996	
997	    fn boolean(&mut self) -> Json {
998	        if self.chars[self.pos] == 't' {
999	            for want in "true".chars() {
1000	                self.expect(want);
1001	            }
1002	            Json::Bool(true)
1003	        } else {
1004	            for want in "false".chars() {
1005	                self.expect(want);
1006	            }
1007	            Json::Bool(false)
1008	        }
1009	    }
1010	
1011	    fn null(&mut self) -> Json {
1012	        for want in "null".chars() {
1013	            self.expect(want);
1014	        }
1015	        Json::Null
1016	    }
1017	}
