1034	/// Parse the sole JSON record on stdout, enforcing the observable contract:
1035	/// exactly one line, exactly the six documented keys in documented order,
1036	/// format 1, fixed algorithm name, valid version range, 64 lowercase hex tag.
1037	fn parse_single_record(stdout: &[u8]) -> Record {
1038	    let text = std::str::from_utf8(stdout).expect("stdout must be valid UTF-8");
1039	    assert!(text.starts_with('{'), "stdout must start with the JSON object");
1040	    let body = text
1041	        .strip_suffix('\n')
1042	        .expect("stdout must end with exactly one newline");
1043	    assert!(!body.is_empty(), "stdout must contain one JSON record");
1044	    assert!(!body.contains('\n'), "stdout must contain exactly one line");
1045	    assert!(!body.ends_with('\r'), "line must not carry a carriage return");
1046	
1047	    let raw = Json::parse(body);
1048	    let keys: Vec<&str> = raw.as_object().iter().map(|(k, _)| k.as_str()).collect();
1049	    assert_eq!(
1050	        keys,
1051	        vec![
1052	            "format",
1053	            "algorithm",
1054	            "key_id",
1055	            "key_version",
1056	            "fields",
1057	            "tag"
1058	        ],
1059	        "record field structure must stay compatible"
1060	    );
1061	
1062	    let fields = raw
1063	        .get("fields")
1064	        .as_array()
1065	        .iter()
1066	        .map(|v| v.as_str().to_string())
1067	        .collect();
1068	
1069	    let rec = Record {
1070	        format: raw.get("format").as_i64(),
1071	        algorithm: raw.get("algorithm").as_str().to_string(),
1072	        key_id: raw.get("key_id").as_str().to_string(),
1073	        key_version: raw.get("key_version").as_i64(),
1074	        fields,
1075	        tag: raw.get("tag").as_str().to_string(),
1076	        raw,
1077	    };
1078	
1079	    assert_eq!(rec.format, 1, "format must always be 1");
1080	    assert_eq!(rec.algorithm, "HMAC-SHA256");
1081	    assert!(
1082	        (1..=u32::MAX as i64).contains(&rec.key_version),
1083	        "key_version out of range: {}",
1084	        rec.key_version
1085	    );
1086	    assert_eq!(rec.tag.len(), 64, "tag must be 64 hex characters");
1087	    assert!(
1088	        rec.tag
1089	            .bytes()
1090	            .all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')),
1091	        "tag must be lowercase hex, got {}",
1092	        rec.tag
1093	    );
1094	    rec
1095	}
