1471	/// Assert that every argv spelling of one invocation exits 0 with empty
1472	/// stderr and byte-identical stdout, then parse and return the shared record
1473	/// together with its exact stdout bytes.
1474	fn expect_equivalent_spellings(label: &str, forms: &[&[&str]]) -> (Record, Vec<u8>) {
1475	    let mut stdout: Option<Vec<u8>> = None;
1476	    for (index, args) in forms.iter().enumerate() {
1477	        let out = run_sign_raw(args);
1478	        assert_eq!(
1479	            out.status.code(),
1480	            Some(0),
1481	            "{label} form {index}: expected exit 0, stderr={:?}",
1482	            String::from_utf8_lossy(&out.stderr)
1483	        );
1484	        assert!(
1485	            out.stderr.is_empty(),
1486	            "{label} form {index}: stderr must be empty, got {:?}",
1487	            String::from_utf8_lossy(&out.stderr)
1488	        );
1489	        if let Some(prev) = &stdout {
1490	            assert_eq!(
1491	                prev,
1492	                &out.stdout,
1493	                "{label} form {index}: the two spellings must produce byte-identical records"
1494	            );
1495	        } else {
1496	            stdout = Some(out.stdout);
1497	        }
1498	    }
1499	    let bytes = stdout.expect("at least one spelling must be provided");
1500	    (parse_single_record(&bytes), bytes)
1501	}
