            assert!(!stderr.contains(LYT_KID), "stderr echoed the key id: {stderr}");
            assert!(!stderr.contains("beta gamma"), "stderr echoed a field: {stderr}");
            assert!(!stderr.contains(LYT_TAG), "stderr echoed the tag/record: {stderr}");
        }
    }
